-- mvtk/tiled/spawners/collectibles.lua
-- Generated by splitting mvtk.tiled.object_spawner handlers by domain.

local OP = require "mvtk.tiled.object_props"
local VisualOwnership = require "mvtk.tiled.visual_ownership"

return function(H)
    local handlers = {}

    local M = H.M
    local Util = H.Util
    local TriggerPayloads = H.TriggerPayloads
    local CollectibleManager = H.CollectibleManager
    local EnemyManager = H.EnemyManager
    local TileSnap = H.TileSnap
    local get_gate_manager = H.get_gate_manager
    local get_boss_arena = H.get_boss_arena
    local get_tile_settings = H.get_tile_settings
    local get_room_world_offset = H.get_room_world_offset
    local to_bool = H.to_bool
    local ambient_component_name = H.ambient_component_name
    local resolve_rect_size_pixels = H.resolve_rect_size_pixels
    local rect_scale_from_size = H.rect_scale_from_size
    local resolve_breakable_swap_extent = H.resolve_breakable_swap_extent
    local parse_color_string = H.parse_color_string
    local non_empty_string = H.non_empty_string
    local resolve_boss_preset = H.resolve_boss_preset
    local resolve_boss_display_name = H.resolve_boss_display_name
    local get_props = H.get_props
    local make_id = H.make_id
    local world_point = H.world_point
    local world_rect = H.world_rect
    local spawn_factory = H.spawn_factory
    local spawn_collection = H.spawn_collection
    local post_collectible_tiled_overrides = H.post_collectible_tiled_overrides
    local apply_scale = H.apply_scale
    local make_scale = H.make_scale
    local send_tiled_props = H.send_tiled_props
    local log_spawn = H.log_spawn
    local log_register = H.log_register
    local get_type_prop = H.get_type_prop
    local record_error = H.record_error
    local normalize_gate_type_name = H.normalize_gate_type_name
    local normalize_gate_item_name = H.normalize_gate_item_name
    local parse_drops_string = H.parse_drops_string
    local resolve_chest_loot_table = H.resolve_chest_loot_table
    local resolve_difficulty_scaling = H.resolve_difficulty_scaling
    local print = H.print
    local polyline_registry = H.polyline_registry

    local function optional_id(value)
        local id = non_empty_string(value)
        return id == "none" and nil or id
    end

function handlers.collectible(object, room_id)
    local props = get_props(object)
    local collectible_type = get_type_prop(props, "collectible_type", object)
    if not collectible_type then
        if non_empty_string(props.relic_id) or non_empty_string(props.relic_name) or non_empty_string(props.relic_description) then
            collectible_type = "relic"
        else
            print("[OBJECT_SPAWNER] Collectible object missing type:", object.id)
            return nil
        end
    end

    local world_x, world_y, pos = world_point(object, room_id)

    -- Build a stable per-map ID so persistence works across runs and
    -- matches authored collection IDs from the exporter.
    local room_key = Util.room_key(room_id)
    local authored_id = string.format("%s_collectible_%d", room_key, tonumber(object.id) or 0)
    local collectible_id = authored_id

    local amount = tonumber(props.amount)
    local custom_config = {
        room_id = room_id,
        id = collectible_id,
        from_object_layer = true,
    }
    if amount then
        custom_config.value = amount
    end
    if props.key_id and props.key_id ~= "" then
        custom_config.item_id = normalize_gate_item_name(props.key_id)
    end
    if props.item_id and props.item_id ~= "" then
        custom_config.item_id = normalize_gate_item_name(props.item_id)
    end
    if props.lore_id and props.lore_id ~= "" then
        custom_config.lore_id = props.lore_id
    end
    if props.lore_text and props.lore_text ~= "" then
        custom_config.lore_text = props.lore_text
    end
    if props.relic_id and props.relic_id ~= "" then
        custom_config.relic_id = props.relic_id
    end
    if props.relic_name and props.relic_name ~= "" then
        custom_config.name = props.relic_name
    end
    if props.relic_description and props.relic_description ~= "" then
        custom_config.description = props.relic_description
    end
    if props.sprite_atlas and props.sprite_atlas ~= "" then
        custom_config.sprite = props.sprite_atlas
    end
    if props.animation and props.animation ~= "" then
        custom_config.animation = props.animation
    end
    if props.area_id and props.area_id ~= "" then
        custom_config.area_id = props.area_id
    end
    if props.area_name and props.area_name ~= "" then
        custom_config.area_name = props.area_name
    end
    if props.reveal_radius ~= nil then
        custom_config.reveal_radius = tonumber(props.reveal_radius) or props.reveal_radius
    end
    if props.show_popup ~= nil then
        custom_config.show_popup = to_bool(props.show_popup, false)
    end
    if props.popup_title and props.popup_title ~= "" then
        custom_config.popup_title = props.popup_title
    end
    if props.popup_description and props.popup_description ~= "" then
        custom_config.popup_description = props.popup_description
    end
    if props.popup_duration ~= nil then
        custom_config.popup_duration = tonumber(props.popup_duration)
    end
    if props.notification and props.notification ~= "" then
        custom_config.notification = props.notification
    end
    if props.respawns ~= nil then
        custom_config.respawns = to_bool(props.respawns, false)
    end

    -- Register collectible data first (includes room_id for completion tracking).
    local spawned_id = CollectibleManager.spawn_collectible(
        collectible_type,
        pos,
        custom_config
    )

    if not spawned_id then
        -- Already collected or invalid type
        return nil
    end

    local prefab_collectible_type = collectible_type
    if prefab_collectible_type:match("^relic_") or props.relic_id or props.relic_name or props.relic_description then
        prefab_collectible_type = "relic"
    end

    -- Spawn the actual collectible game object.
    local instance = spawn_factory("collectible_factory", pos, {
        collectible_type = prefab_collectible_type,
        collectible_id = authored_id,
    }, 1, "collectible")

    if not instance then
        return { spawn_id = spawned_id, instance_url = nil }
    end

    post_collectible_tiled_overrides(instance, collectible_type, collectible_id, room_id, props)

    log_spawn("collectible", collectible_type, world_x, world_y)
    return { spawn_id = spawned_id, instance_url = instance }
end

--- Spawn an enemy from Tiled object
-- Tiled properties (all optional, override enemy_types.lua defaults):
--   enemy_type: string (enemy ID from enemy_types.lua) - REQUIRED
--   loot_table: string (override loot table)
--   elite: bool (elite variant with boosted stats)
--   patrol_route: string (path object name to follow)
--   behavior: string (override behavior type)
--   faction: string (faction/group ID for AI)
--   group_id: string (group for coordinated behavior)
--   ally_detection_range: number (range to call allies)
--   health_mult: number (multiply base health)
--   damage_mult: number (multiply base damage)
--   speed_mult: number (multiply base speed)

function handlers.ability(object, room_id)
    local props = get_props(object)
    local ability_id = optional_id(get_type_prop(props, "ability_id", object))
    if not ability_id then
        print("[OBJECT_SPAWNER] Ability pickup missing ability_id")
        return nil
    end

    local world_x, world_y, pos = world_point(object, room_id)

    local collectible_type = "ability_" .. ability_id

    -- Stable ID based on Tiled room + object ID, aligned with authored collections.
    local room_key = Util.room_key(room_id)
    local authored_id = string.format("%s_ability_%d", room_key, tonumber(object.id) or 0)
    local collectible_id = authored_id

    local custom_config = {
        room_id = room_id,
        id = collectible_id,
        from_object_layer = true,
        show_popup = to_bool(props.show_popup, false),
        popup_title = props.popup_title,
        popup_description = props.popup_description,
    }

    -- Register with manager first so completion tracking is correct.
    local spawn_id = CollectibleManager.spawn_collectible(
        collectible_type,
        pos,
        custom_config
    )

    if not spawn_id then
        return nil
    end

    -- Spawn the actual collectible game object.
    local instance = spawn_factory("collectible_factory", pos, {
        collectible_type = collectible_type,
        collectible_id = authored_id,
    }, 1, "ability collectible")

    if not instance then
        return { spawn_id = spawn_id, instance_url = nil }
    end

    post_collectible_tiled_overrides(instance, collectible_type, collectible_id, room_id, props, {
        ability_id = ability_id,
        show_popup = custom_config.show_popup,
        popup_title = custom_config.popup_title,
        popup_description = custom_config.popup_description,
    })

    log_spawn("ability pickup", ability_id, world_x, world_y)
    return { spawn_id = spawn_id, instance_url = instance }
end

--- Handle authored chests

-- Authored chests are always baked into the editable room collection.
function handlers.chest(object, room_id)
    print(string.format("[OBJECT_SPAWNER] SKIPPING chest creation for '%s' - chests created by editor script", object.name or object.id))
    return nil
end

--- Handle moving platform object
-- Tiled properties:
--   platform_type: string ("horizontal", "vertical", "path", "circular")
--   speed: number (pixels per second, converted to duration)
--   distance: number (travel distance for linear platforms)
--   wait_time: number (pause at endpoints)
--   radius: number (for circular motion)
--   loop_mode: string ("pingpong", "loop", "once")
--   path_id: string (reference to polyline object for path mode)
-- Polyline data: If object has polyline property, use it for path mode
--- Handle moving platform object
-- DISABLED: Platforms are now created by editor script during tilemap import
-- Tiled properties:
--   platform_type: string ("horizontal", "vertical", "path", "circular")
--   distance: number (travel distance for linear platforms)
--   duration: number (time for one cycle)
--   wait: number (pause at endpoints)
--   loop_mode: string ("pingpong", "loop", "once")
--   radius: number (for circular motion)
--   start_angle: number (starting angle in degrees)
--   polyline: array of points (for path motion)

function handlers.lore_item(object, room_id)
    local props = get_props(object)
    local lore_id = make_id(props, "lore_id", "lore", object, room_id)
    local _, _, pos = world_point(object, room_id)

    local text_value = props.text
    if text_value == nil then text_value = props.content end
    local category_value = props.category
    if category_value == nil then category_value = props.lore_type end

    local instance = spawn_factory("lore_item_factory", pos, {
        lore_id = lore_id,
        title = props.title or "",
        text = text_value or "",
        category = category_value or "notes",
        auto_pickup = to_bool(props.auto_pickup, false),
        destroyable = to_bool(props.destroyable, false),
        trigger_once = to_bool(props.trigger_once, false),
        unlock_flag = props.unlock_flag or "",
        requires_flag = props.requires_flag or "",
        sound_id = optional_id(props.sound_id) or "",
        particle_id = optional_id(props.particle_id) or "",
    }, 1, "lore item")

    if not instance then return nil end

    send_tiled_props(instance, props)

    log_spawn("lore item", lore_id, pos.x, pos.y)
    return instance
end

--- Handle checkpoint object (auto-save point, different from save_point)
-- Checkpoints save automatically when player touches them (no interaction needed)
-- Tiled properties:
--   checkpoint_id: string (unique identifier)
--   respawn_facing: number (1 = right, -1 = left)
--   trigger_once: bool (if true, only activates once per session)
--   sound_id: string (sound when checkpoint activated)
--   particle_id: string (particle effect when activated)

-- Handler aliases for authored object type synonyms.
handlers.journal_entry = handlers.lore_item
handlers.note = handlers.lore_item

    return handlers
end
